 return rows.Where(r=>(!favoritesOnly||favorites.Contains(r.Id))&&(paletteSearch==""||(r.Name+" "+r.Id).Contains(paletteSearch,StringComparison.OrdinalIgnoreCase))).OrderByDescending(r=>favorites.Contains(r.Id)).ToList();}
