  if(editorCategory=="prefab"){try{var candidate=map.Clone();MapWorkshop.Prefab(candidate,editorSelection.X,editorSelection.Y,selectedAsset);package.ValidateMap(candidate);Snapshot();map=candidate;mapVersion++;message="Building and roof group stamped.";}catch(ContentException e){message=e.Message;}return true;}
  if(editorCategory=="object"){try{var candidate=map.Clone();var parts=selectedAsset.Split(':');var o=new MapObject{Id="object."+Guid.NewGuid().ToString("N")[..12],Kind=parts[0],Name=parts[0],X=editorSelection.X,Y=editorSelection.Y};if(o.Kind=="npc"){o.Name="New resident";o.Role=parts[1];o.Text="Welcome to Greyhaven.";}if(o.Kind=="encounter"){o.Archetype=parts[1];o.Name=CombatRules.Enemy(parts[1]).Name;}if(o.Kind=="door"||o.Kind=="gate")o.Visual="door";if(o.Kind=="container"){o.Visual="chest";o.Loot=[new(){Definition="greyhaven.item.healing-tonic",Amount=2}];}if(o.Kind=="key")o.Visual="scroll";if(o.Kind=="portal")o.TargetId=candidate.Objects.FirstOrDefault(x=>x.Kind=="portal")?.Id??"";if(o.Kind=="lever")o.TargetId=candidate.Objects.FirstOrDefault(x=>x.Kind=="gate")?.Id??"";candidate.Objects.Add(o);package.ValidateMap(candidate);Snapshot();map=candidate;inspector=o;areaInspector=null;selectedObject=o.Id;mapVersion++;message="Placed "+o.Kind+". F4 edits name, text, role, target and loot.";}catch(ContentException e){message=e.Message;}return true;}
